Mei - Halloween
																					Ativo por: 7 Dias 23 Horas 32 Min 16 Seg

									$(document).ready(function () {
                      $('#clock-799').countdown("2026-11-08 23:59:59", function(event) {

                          var dias = event.offset.totalDays;

                          if (dias > 0) {
                              $(this).html(
                                  'Ativo por: ' +
                                  dias + (dias == 1 ? ' Dia ' : ' Dias ') +
                                  event.strftime('%H Horas %M Min %S Seg')
                              );
                          } else {
                              var horas = event.offset.hours;
                              $(this).html(
                                  'Ativo por: ' +
                                  horas + (horas == 1 ? ' Hora ' : ' Horas ') +
                                  event.strftime('%M Min %S Seg')
                              );
                          }

                      });
                  });

